    reader = csv.reader(f, delimiter='\t')
    for row in reader:
        cusip = row[4]
        value = int(row[6]) if row[6] else 0
        if cusip in q3_holdings:
            q3_holdings[cusip] += value
        else:
            q3_holdings[cusip] = value

# Calculate changes
changes = []
all_cusips = set(q2_holdings.keys()) | set(q3_holdings.keys())
