# Sort by change descending
changes.sort(key=lambda x: x[1], reverse=True)

# Print top 5
print("Top 5 stocks with increased investment:")
for i, (cusip, change, q2, q3) in enumerate(changes[:5]):
    print(f"{i+1}. CUSIP: {cusip}, Change: ${change:,}, Q2: ${q2:,}, Q3: ${q3:,}")
